def linear_search(items, target):
    steps = 0
    for item in items:
        steps += 1
        if item == target:
            break
    return steps

def binary_search(items, target):
    steps, low, high = 0, 0, len(items) - 1
    while low <= high:
        steps += 1
        mid = (low + high) // 2
        if items[mid] == target:
            break
        if items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return steps

def compare_all_pairs(items):
    steps = 0
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            steps += 1
    return steps

print(f"{'n':>9} {'linear':>9} {'binary':>7} {'all pairs':>14}")
for n in (10, 100, 1_000, 10_000):
    data = list(range(n))
    worst = n - 1                      # the last item: the worst case for a linear search
    print(f"{n:>9,} {linear_search(data, worst):>9,} {binary_search(data, worst):>7,} {compare_all_pairs(data):>14,}")
